def submit(self, message: Message[FilteredPayload | int]) -> None:
    # Throttle expensive health-check + Redis LLEN fanout to avoid
    # multiplying Redis traffic with multiple flusher processes.
    now = time.time()
    if now - self._last_submit_maintenance > 1.0:
        self._last_submit_maintenance = now
        self._ensure_processes_alive()
        for buffer in self.buffers.values():
            buffer.record_stored_segments()
